    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Kings Roofing & Contracting LLC is a roofing, siding, gutter, and RV garage contractor, which falls outside ForgeX's target segment of HVAC, plumbing, and electrical contractors."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because the company is outside ForgeX's industry segment and no confirmed operational problem has been established."
  },
  "humanReview": [
    "Not applicable as no automation solution is recommended; if the company ever adopted roofing automation, human review would be required for roof inspection photo reports, structural/code assessments, permit filings, and written estimates."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Engaging a roofing and exterior construction contractor falls outside ForgeX's standardized playbooks and integrations built for HVAC, plumbing, and electrical field-service workflows."
    },
    {
      "type": "compliance",
      "description": "The company notes on its homepage that Idaho law reserves negotiating insurance claim settlements for licensed public adjusters, so any communication or estimating workflow touching storm damage claims must avoid unauthorized claim negotiation."
    },
    {
      "type": "security",
      "description": "Using a consumer @gmail.com address for customer communications and financing or insurance documentation may lack centralized domain access controls."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website does not publish fixed service prices (only general FAQ commentary that a typical asphalt shingle replacement falls in the 'mid-five figures' and an illustrative financing page comparison of a '$500 repair' vs. '$5,000 repair').",
      "Because the company is outside ForgeX's segment and no ForgeX solution is recommended, commercial value and implementation cost are not applicable."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Managing Member",
      "Project Lead / Operations Manager"
    ],
    "people": [],
