      },
      {
        "url": "https://www.kingsroofingandcontracting.com/about/",
        "usedFor": "Checked for owner or leadership names, family-owned status, GAF certification, and licensing details."
      },
      {
        "url": "https://www.kingsroofingandcontracting.com/services/",
        "usedFor": "Verified full scope of services to confirm the company does not provide HVAC, plumbing, or electrical services."
      },
      {
        "url": "https://www.kingsroofingandcontracting.com/contact/",
        "usedFor": "Verified phone handling practices (live person answering, no phone tree) and estimate turnaround times (1–2 days)."
      },
      {
        "url": "https://www.kingsroofingandcontracting.com/free-roof-quote/",
        "usedFor": "Verified lead capture form setup and quoting process."
      },
      {
        "url": "https://www.kingsroofingandcontracting.com/financing/",
        "usedFor": "Checked financing workflows and whether any third-party financing portal or pricing was embedded."
      },
      {
        "url": "https://www.kingsroofingandcontracting.com/faq/",
